package main

import (
	"fmt"
	"math"
)

func pageSlow(slow float64, servers int) float64 {
	return 1 - math.Pow(1-slow, float64(servers))
}

func main() {
	slow := 0.01
	servers := 100
	for _, pods := range []int{10, 20, 40} {
		fmt.Printf("pods=%d: %.1f%% of pages are slow\n", pods, pageSlow(slow, servers)*100)
	}
}
